-- Biblioteca de ejercicios del box demo (ADR 0050): halterofilia, fuerza, gimnásticos, cardio,
-- kettlebell, accesorios y movilidad, cada uno con cómo se hace, en qué fijarse, los errores de
-- siempre y cómo se escala. Los de halterofilia y fuerza van enlazados al catálogo de movimientos
-- (máximas y kilos por porcentaje). Sin vídeos: los pone cada box. Idempotente: salta los que ya
-- existen con el mismo nombre.
INSERT INTO "exercises" ("organization_id", "name", "category", "equipment", "movement_code", "section_id", "description", "coaching_points", "common_faults", "scaling", "created_by")
SELECT o."id", v."name", v."category", v."equipment"::jsonb, v."movement",
  (SELECT s."id" FROM "sections" s WHERE s."organization_id" = o."id" AND s."name" = v."section"),
  v."description", v."points", v."faults", v."scaling",
  (SELECT u."id" FROM "users" u WHERE u."email" = 'coach@demo.test')
FROM "organizations" o
CROSS JOIN (VALUES
  ('Back squat', 'strength', '["barbell"]', 'back_squat', 'CrossFit', 'Sentadilla con la barra apoyada en la parte alta de la espalda. Se baja con la cadera por debajo de la rodilla y se sube hasta la extensión completa de cadera y rodilla.', E'Pies a la anchura de los hombros, puntas algo abiertas.\nPeso en todo el pie, talón pegado al suelo.\nRodillas en la línea de los pies.\nTronco firme: aire y abdomen antes de bajar.', E'Talones que se levantan.\nRodillas que caen hacia dentro.\nPerder la curva lumbar abajo.\nSubir primero la cadera y doblar el tronco.', E'Goblet squat con kettlebell o mancuerna.\nSentadilla a cajón para marcar la profundidad.\nMenos carga y tempo lento (3 segundos de bajada).'),
  ('Front squat', 'strength', '["barbell"]', 'front_squat', 'CrossFit', 'Sentadilla con la barra en rack frontal, sobre los hombros y con los codos altos. Pide más tronco vertical y más core que la back squat.', E'Codos altos durante toda la repetición.\nBarra apoyada en los hombros, no en las manos.\nBajar entre las piernas con el tronco recto.', E'Codos que caen y la barra se va hacia delante.\nTalones despegados.\nRedondear la espalda alta al subir.', E'Agarre con dos dedos o con correas si falta movilidad de muñeca.\nGoblet squat.\nFront squat con mancuernas.'),
  ('Overhead squat', 'strength', '["barbell"]', 'overhead_squat', 'CrossFit', 'Sentadilla con la barra bloqueada por encima de la cabeza con agarre ancho. Es la posición de recepción de la arrancada.', E'Codos bloqueados y axilas mirando adelante.\nBarra encima de la mitad del pie.\nEmpujar la barra hacia arriba durante toda la bajada.', E'Brazos que se doblan.\nBarra que se va por delante de la cabeza.\nTronco que cae hacia delante.', E'Con PVC o barra técnica.\nSentadilla con PVC por encima a una profundidad cómoda.\nTrabajo de movilidad de hombro y tobillo antes.'),
  ('Peso muerto', 'strength', '["barbell"]', 'deadlift', 'CrossFit', 'Levantar la barra del suelo hasta la extensión completa de cadera con la espalda neutra.', E'Barra sobre la mitad del pie, pegada a las espinillas.\nHombros un poco por delante de la barra al empezar.\nEmpujar el suelo con las piernas; la barra sube rozando las piernas.\nTerminar con cadera y rodilla extendidas, sin echar el tronco atrás.', E'Redondear la espalda.\nBarra separada del cuerpo.\nSubir la cadera antes que la barra.\nHiperextender la lumbar arriba.', E'Kettlebell deadlift.\nPeso muerto desde bloques o discos.\nMenos carga y foco en la posición inicial.'),
  ('Strict press', 'strength', '["barbell"]', 'strict_press', 'CrossFit', 'Press de hombros de pie sin ayuda de las piernas, desde el rack frontal hasta bloquear por encima de la cabeza.', E'Glúteos y abdomen apretados, sin arquear la lumbar.\nLa cabeza se aparta y vuelve a pasar bajo la barra.\nBloquear con la barra encima de los hombros.', E'Arquear la espalda para ayudarse.\nTerminar con la barra por delante.\nDoblar las rodillas.', E'Press con mancuernas.\nMenos carga.\nPress con barra técnica para aprender la trayectoria.'),
  ('Push press', 'strength', '["barbell"]', 'push_press', 'CrossFit', 'Press de hombros con un impulso de piernas: flexión corta (dip), extensión explosiva (drive) y los brazos terminan el movimiento.', E'Dip corto y vertical, con el peso en los talones.\nExtensión de piernas completa antes de empujar con los brazos.\nBloquear arriba con la barra detrás de la cabeza.', E'Dip demasiado profundo o con las rodillas hacia delante.\nEmpezar a empujar con los brazos demasiado pronto.', E'Push press con mancuernas.\nMenos carga y foco en el ritmo del dip y el drive.'),
  ('Thruster', 'strength', '["barbell"]', 'thruster', 'CrossFit', 'Front squat que enlaza sin pausa con un press por encima de la cabeza, aprovechando la subida de la sentadilla.', E'Codos altos abajo para que la barra no se caiga.\nSubir rápido y usar la cadera para lanzar la barra.\nCabeza fuera del camino de la barra.', E'Empujar con los brazos antes de extender la cadera.\nCodos bajos en la sentadilla.\nNo bloquear arriba.', E'Thrusters con mancuernas o con wall ball.\nMenos carga.\nFront squat y push press por separado.'),
  ('Bench press', 'strength', '["barbell"]', 'bench_press', 'CrossFit', 'Press tumbado en banco: la barra baja al pecho y se empuja hasta bloquear los codos.', E'Escápulas juntas y abajo.\nPies firmes en el suelo.\nLa barra baja a la línea del esternón.\nSiempre con alguien que ayude en cargas altas.', E'Rebotar la barra en el pecho.\nCodos totalmente abiertos a 90 grados.\nLevantar los glúteos del banco.', E'Press con mancuernas.\nFlexiones.'),
  ('Arrancada', 'weightlifting', '["barbell"]', 'snatch', 'CrossFit', 'Llevar la barra del suelo a encima de la cabeza en un solo movimiento, recibiéndola en sentadilla con agarre ancho.', E'Primer tirón lento y controlado.\nBarra pegada al cuerpo.\nExtensión completa de cadera antes de tirar con los brazos.\nMeterse rápido debajo de la barra.', E'Tirar con los brazos demasiado pronto.\nBarra que se separa del cuerpo.\nRecibir con los brazos blandos.', E'Hang power snatch.\nArrancada con PVC o barra técnica.\nTrabajo por partes: posición de colgado, tirón, recepción.'),
  ('Power snatch', 'weightlifting', '["barbell"]', 'power_snatch', 'CrossFit', 'Arrancada recibida por encima de la paralela, en una sentadilla parcial.', E'Mismo tirón que la arrancada completa.\nPies que se abren un poco al recibir.\nBloquear con los codos firmes.', E'Saltar hacia delante.\nRecibir con los brazos doblados y terminar en press.', E'Hang power snatch.\nPower snatch con mancuerna.'),
  ('Cargada', 'weightlifting', '["barbell"]', 'squat_clean', 'CrossFit', 'Llevar la barra del suelo al rack frontal, recibiéndola en sentadilla completa.', E'Hombros por delante de la barra en el primer tirón.\nExtensión de cadera completa antes de tirar.\nCodos rápidos hacia delante al recibir.', E'Tirar con los brazos.\nRecibir con los codos bajos.\nAlejar la barra del cuerpo.', E'Hang squat clean.\nCargada con mancuernas o kettlebells.\nFront squat para la posición de recepción.'),
  ('Power clean', 'weightlifting', '["barbell"]', 'power_clean', 'CrossFit', 'Cargada recibida por encima de la paralela.', E'Barra pegada al cuerpo.\nExtensión explosiva de cadera.\nCodos rápidos al rack frontal.', E'Saltar hacia atrás.\nRecibir sobre los dedos de los pies.\nTirar con los brazos doblados.', E'Hang power clean.\nPower clean con mancuernas.'),
  ('Clean and jerk', 'weightlifting', '["barbell"]', 'clean_and_jerk', 'CrossFit', 'Cargada hasta el rack frontal y envión por encima de la cabeza.', E'Recuperar la posición antes del envión.\nDip vertical y drive explosivo.\nBloquear por encima con los pies firmes.', E'Envión con la barra por delante.\nPrisa entre la cargada y el envión.', E'Power clean y push jerk.\nMancuernas.\nMenos carga y trabajo técnico.'),
  ('Push jerk', 'weightlifting', '["barbell"]', 'push_jerk', 'CrossFit', 'Envión en el que el atleta se mete debajo de la barra con una flexión de piernas, sin cambiar la posición de los pies.', E'Dip y drive como en el push press.\nPresionar contra la barra mientras se baja.\nTerminar de pie con la barra bloqueada.', E'Recibir con los brazos blandos.\nDip hacia delante.', E'Push press.\nPush jerk con PVC para el ritmo.'),
  ('Split jerk', 'weightlifting', '["barbell"]', 'split_jerk', 'CrossFit', 'Envión recibido con las piernas en tijera, un pie delante y el otro detrás.', E'Pie delantero plano, pie de atrás sobre los dedos.\nCadera entre las dos piernas.\nVolver primero el pie de delante.', E'Tijera demasiado corta o demasiado estrecha.\nTronco inclinado.', E'Practicar la tijera sin barra.\nSplit jerk detrás de la nuca con poca carga.'),
  ('Dominada', 'gymnastics', '["pullup_bar"]', NULL::text, 'CrossFit', 'Desde colgado, subir hasta que la barbilla pase la barra. Puede ser estricta o con kipping.', E'Hombros activos al empezar.\nEn kipping, el balanceo sale de la cadera y del hombro, no de las piernas.\nBarbilla por encima de la barra.', E'Media repetición: brazos sin estirar abajo.\nKipping sin control.\nMentón que no pasa la barra.', E'Dominada con banda elástica.\nRing rows.\nDominadas negativas lentas.\nJumping pull-ups.'),
  ('Chest to bar', 'gymnastics', '["pullup_bar"]', NULL::text, 'CrossFit', 'Dominada en la que el pecho toca la barra por debajo de las clavículas.', E'Kipping más potente que en la dominada.\nLlevar el pecho a la barra, no la barbilla.\nCodos hacia atrás al final.', E'Tocar con la barbilla.\nNo estirar los brazos abajo.', E'Dominadas.\nChest to bar con banda.'),
  ('Toes to bar', 'gymnastics', '["pullup_bar"]', NULL::text, 'CrossFit', 'Desde colgado, tocar la barra con los dos pies a la vez entre las manos.', E'Empujar la barra hacia abajo con los brazos rectos.\nKipping desde la posición de hollow.\nPies juntos al tocar.', E'Tocar con un solo pie.\nBalanceo sin control que corta la serie.', E'Knee raises (rodillas al pecho).\nToes to bar en el suelo (V-ups).\nPiernas a la mitad de la altura.'),
  ('Bar muscle-up', 'gymnastics', '["pullup_bar"]', NULL::text, 'CrossFit', 'Pasar de colgado a apoyo por encima de la barra con los brazos bloqueados.', E'Kipping potente y cadera a la barra.\nTirar de la barra hacia la cadera.\nGirar el tronco por encima y empujar.', E'Subir una sola mano primero (chicken wing).\nKipping corto.', E'Chest to bar más jumping bar muscle-up.\nBar muscle-up con banda.\nDips en barra para la salida.'),
  ('Ring muscle-up', 'gymnastics', '["rings"]', NULL::text, 'CrossFit', 'Pasar de colgado a apoyo por encima de las anillas con un tirón y una transición.', E'Falso agarre si es estricto.\nAnillas pegadas al cuerpo en la transición.\nCodos rápidos hacia atrás.', E'Anillas separadas del cuerpo.\nTransición lenta.', E'Transiciones en el suelo con anillas bajas.\nRing dips más pull-ups.\nMuscle-up con banda.'),
  ('Handstand push-up', 'gymnastics', '["bodyweight"]', NULL::text, 'CrossFit', 'Flexión en el pino contra la pared: la cabeza toca el suelo y los brazos se bloquean arriba.', E'Manos un poco más anchas que los hombros.\nCabeza y manos forman un triángulo.\nAbdomen firme para no arquear.', E'Arquear la espalda.\nCabeza que no toca el suelo o el cojín.', E'Pike push-ups en cajón.\nHSPU con más cojines debajo de la cabeza.\nPress con mancuernas.'),
  ('Flexión', 'gymnastics', '["bodyweight"]', NULL::text, NULL::text, 'Desde plancha, bajar hasta que el pecho toque el suelo y empujar hasta bloquear.', E'Cuerpo recto de los talones a la cabeza.\nCodos a unos 45 grados.\nPecho al suelo en cada repetición.', E'Cadera que cae o que se sube.\nMedia repetición.', E'Flexiones con las manos en un cajón.\nFlexiones con las rodillas en el suelo.'),
  ('Burpee', 'gymnastics', '["bodyweight"]', NULL::text, NULL::text, 'Pecho al suelo, levantarse y saltar con una palmada por encima de la cabeza.', E'Pecho y muslos tocan el suelo.\nCadera extendida en el salto.\nRitmo constante mejor que sprints.', E'No tocar el suelo con el pecho.\nNo extender la cadera arriba.', E'Burpee sin salto.\nUp-downs sin flexión.\nBajar con las manos en un cajón.'),
  ('Box jump', 'gymnastics', '["box"]', NULL::text, 'CrossFit', 'Saltar al cajón con los dos pies y extender la cadera arriba.', E'Aterrizar con los pies enteros sobre el cajón.\nExtender cadera y rodilla arriba.\nBajar andando si hay fatiga.', E'Aterrizar con los talones fuera.\nRebotar al bajar con las piernas rígidas.', E'Cajón más bajo.\nStep-ups.\nBox jump over.'),
  ('Air squat', 'gymnastics', '["bodyweight"]', NULL::text, NULL::text, 'Sentadilla sin carga, con la cadera por debajo de la rodilla y la extensión completa arriba.', E'Peso en los talones.\nRodillas hacia fuera.\nBrazos al frente para equilibrar.', E'Profundidad corta.\nTalones que se levantan.', E'Sentadilla a cajón.\nSentadilla agarrado a algo para el equilibrio.'),
  ('Double unders', 'gymnastics', '["jump_rope"]', NULL::text, 'CrossFit', 'La comba pasa dos veces bajo los pies en cada salto.', E'Salto un poco más alto que en simples, con las piernas casi rectas.\nGiro de muñecas, no de brazos.\nCodos cerca del cuerpo.', E'Patadas hacia atrás (salto de mula).\nBrazos que giran en círculo grande.', E'Single unders (el doble de repeticiones).\nIntentos de dobles con simples entre medias.'),
  ('Remo', 'monostructural', '["rower"]', NULL::text, NULL::text, 'Remo en máquina: piernas, tronco y brazos en la tirada; brazos, tronco y piernas en la vuelta.', E'Empujar con las piernas, no tirar con los brazos.\nTronco ligeramente atrás al final.\nResistencia (damper) entre 5 y 7.', E'Doblar los brazos demasiado pronto.\nRodillas que suben antes de que pasen las manos.', E'Menos metros o calorías.\nBici o carrera según el objetivo.'),
  ('Bike', 'monostructural', '["bike"]', NULL::text, NULL::text, 'Bici de aire (Assault o Echo): piernas y brazos a la vez, medida en calorías o metros.', E'Ajustar el sillín a la altura de la cadera.\nEmpujar y tirar con los brazos.\nRitmo que se pueda sostener.', 'Salir a tope y quedarse sin aire.', E'Menos calorías.\nRemo o carrera.'),
  ('SkiErg', 'monostructural', '["ski"]', NULL::text, 'HYROX', 'Ergómetro de esquí: tirón vertical con los dos brazos y el tronco.', E'Cadera atrás y tronco que baja con los brazos.\nBrazos casi rectos.\nVolver a la posición alta sin prisa.', E'Tirar solo con los brazos.\nSentadilla en lugar de bisagra de cadera.', E'Menos metros.\nRemo.'),
  ('Carrera', 'monostructural', '["bodyweight"]', NULL::text, 'HYROX', 'Carrera a pie, en la calle o en cinta, por distancia o por tiempo.', E'Zancada corta y cadencia alta.\nApoyo bajo el cuerpo, no por delante.\nRespirar por la nariz en los ritmos suaves.', 'Salir demasiado rápido en las primeras repeticiones.', E'Menos distancia.\nRemo o bici si hay molestias.'),
  ('Kettlebell swing', 'kettlebell', '["kettlebell"]', NULL::text, 'CrossFit', 'Balanceo de la kettlebell con una bisagra de cadera. Ruso: hasta la altura de los ojos; americano: por encima de la cabeza.', E'La fuerza sale de la cadera, no de los brazos.\nEspalda neutra en la bisagra.\nGlúteos apretados arriba.', E'Sentadilla en lugar de bisagra.\nTirar con los brazos.\nArquear la lumbar arriba en el americano.', E'Swing ruso.\nMenos peso.\nKettlebell deadlift para aprender la bisagra.'),
  ('Wall ball', 'accessory', '["wall_ball"]', NULL::text, NULL::text, 'Sentadilla con el balón en el pecho y lanzamiento a la diana al subir.', E'Codos bajo el balón.\nSentadilla completa.\nLanzar con la cadera y recibir bajando.', E'Balón que se va hacia delante.\nNo llegar a la diana.\nProfundidad corta.', E'Balón más ligero.\nDiana más baja.\nThrusters con el balón sin lanzar.'),
  ('Sled push', 'accessory', '["sled"]', NULL::text, 'HYROX', 'Empujar el trineo cargado una distancia con los brazos rectos o doblados.', E'Tronco inclinado y bajo.\nPasos cortos y rápidos.\nBrazos firmes.', E'Erguirse y perder el empuje.\nPasos largos que frenan.', E'Menos carga.\nTramos más cortos.'),
  ('Sandbag lunges', 'accessory', '["sandbag"]', NULL::text, 'HYROX', 'Zancadas caminando con el saco sobre los hombros.', E'La rodilla de atrás roza el suelo.\nTronco recto.\nPaso largo y estable.', E'Rodilla delantera que se va hacia dentro.\nTronco inclinado hacia delante.', E'Saco más ligero.\nZancadas sin carga.'),
  ('Burpee broad jump', 'gymnastics', '["bodyweight"]', NULL::text, 'HYROX', 'Burpee seguido de un salto horizontal hacia delante con los dos pies.', E'Pecho al suelo.\nSalto largo con los brazos.\nCaer con los pies juntos y seguir.', E'Salto corto que alarga la prueba.\nNo tocar el suelo con el pecho.', E'Burpee y salto por separado.\nPasos en lugar de salto.'),
  ('Farmer carry', 'accessory', '["kettlebell", "dumbbell"]', NULL::text, NULL::text, 'Caminar con una carga en cada mano y los brazos estirados.', E'Hombros abajo y atrás.\nTronco firme y recto.\nPasos cortos.', E'Hombros encogidos.\nInclinarse hacia un lado.', E'Menos peso.\nTramos más cortos.'),
  ('Hollow hold', 'accessory', '["bodyweight"]', NULL::text, NULL::text, 'Aguantar boca arriba con la lumbar pegada al suelo y brazos y piernas estirados y separados del suelo.', E'Lumbar pegada al suelo.\nBrazos junto a las orejas.\nPiernas tan bajas como permita la lumbar.', E'Lumbar que se despega.\nCuello en tensión.', E'Rodillas dobladas.\nBrazos al lado del cuerpo.'),
  ('Movilidad de hombro con PVC', 'mobility', '["other"]', NULL::text, NULL::text, 'Pass-through con un PVC: llevarlo de delante a detrás por encima de la cabeza con los brazos rectos.', E'Brazos rectos.\nCostillas abajo.\nCerrar el agarre poco a poco.', E'Doblar los codos.\nArquear la espalda.', E'Agarre más ancho.\nMenos amplitud.'),
  ('Movilidad de cadera 90/90', 'mobility', '["bodyweight"]', NULL::text, NULL::text, 'Sentado en el suelo con las dos rodillas a 90 grados, girar de un lado a otro sin usar las manos.', E'Tronco recto.\nMovimiento lento y controlado.\nRespirar en la posición final.', E'Inclinarse para compensar.\nForzar el rango.', E'Con las manos apoyadas detrás.\nMenos rango.')
) AS v("name", "category", "equipment", "movement", "section", "description", "points", "faults", "scaling")
WHERE o."slug" = 'demo-box'
  AND NOT EXISTS (
    SELECT 1 FROM "exercises" e WHERE e."organization_id" = o."id" AND lower(e."name") = lower(v."name")
  );
